#include <vector>
#include <algorithm>

class Solution {
public:
    int maxStationGap(std::vector<int>& stations) {
        if (stations.size() < 2) return 0;
        std::sort(stations.begin(), stations.end());
        int maxGap = 0;
        for (size_t i = 1; i < stations.size(); ++i) {
            maxGap = std::max(maxGap, stations[i] - stations[i - 1]);
        }
        return maxGap;
    }
};

import java.util.*;

class Solution {
    public int maxStationGap(int[] stations) {
        if (stations.length < 2) return 0;
        Arrays.sort(stations);
        int maxGap = 0;
        for (int i = 1; i < stations.length; i++) {
            maxGap = Math.max(maxGap, stations[i] - stations[i - 1]);
        }
        return maxGap;
    }
}

function maxStationGap(stations) {
    if (stations.length < 2) return 0;
    stations.sort((a, b) => a - b);
    let maxGap = 0;
    for (let i = 1; i < stations.length; i++) {
